`timescale 1ns / 1ps

//
// Testbench for top::UartSender.
//
// Conventions (matching the DUT as generated by `vir build`):
//
//   * `data_send` is a Valid[Word[8]], packed as {valid, data[7:0]}.
//   * `tx` idles HIGH. The DUT enters each bit state by loading
//     `baud_counter` with 420 and decrements it while it is > 0, so
//     each bit occupies 421 clock cycles (counts 420 down to 0).
//     BIT_CYCLES below must match that.
//
// The frame format is 8N1: start bit low, 8 data bits LSB first,
// stop bit high.
//
// `uart_rx_byte` is the reusable receiver task: it waits for the
// start-bit edge, samples every bit at its midpoint, checks the stop
// bit, and returns the received byte.
//

module uart_sender_tb;

    // Clock cycles per UART bit (baud_counter load value + 1).
    localparam integer BIT_CYCLES = 421;

    // 48 MHz clock: period = 1000/48 = 20.8333 ns.
    localparam real CLK_PERIOD_NS = 1000.0 / 48.0;

    // Number of bytes in the test sequence.
    localparam integer NUM_TEST_BYTES = 5;

    // Watchdog sized from the actual run length: 10 bits per frame,
    // ~20.84 ns per cycle, times 3 for inter-frame idle and start-up.
    // (A hardcoded value rots as soon as BIT_CYCLES changes: at
    // 420+ cycles per bit, five frames need ~510 us.)
    localparam integer TIMEOUT_NS = 3 * NUM_TEST_BYTES * 10 * BIT_CYCLES * 21;

    //
    // DUT connections
    //

    reg         clock;
    reg         data_send_valid;
    reg  [7:0]  data_send_payload;
    wire        tx;

    \top::UartSender dut (
        .clock(clock),
        .data_send({data_send_valid, data_send_payload}),
        .tx(tx)
    );

    initial clock = 1'b0;
    always #(CLK_PERIOD_NS / 2.0) clock = ~clock;

    //
    // UART receiver task
    //
    // Receives one 8N1 byte on `tx`, sampling each bit at its midpoint.
    //

    task uart_rx_byte(
        output [7:0] byte_out,
        output       stop_bit_ok
    );
        integer bit_i;
        begin
            byte_out    = 8'hxx;
            stop_bit_ok = 1'b0;

            // Arm only from a solidly idle line: glitches and 1->X
            // transitions also produce negedge events.
            if (tx !== 1'b1) begin
                @(posedge tx);
            end

            // Wait for the start bit: a falling edge on the idle-high line.
            @(negedge tx);

            // Jump to the middle of the start bit and verify it is low.
            #(BIT_CYCLES * CLK_PERIOD_NS / 2.0);
            if (tx !== 1'b0) begin
                $display("[%0t] FAIL: start bit not low at its midpoint", $time);
            end

            // Sample the 8 data bits, LSB first, at their midpoints.
            for (bit_i = 0; bit_i < 8; bit_i = bit_i + 1) begin
                #(BIT_CYCLES * CLK_PERIOD_NS);
                byte_out[bit_i] = tx;
            end

            // Check the stop bit at its midpoint.
            #(BIT_CYCLES * CLK_PERIOD_NS);
            stop_bit_ok = (tx === 1'b1);
        end
    endtask

    //
    // Stimulus helper
    //

    task send_byte(
        input [7:0] b
    );
        begin
            @(posedge clock);
            data_send_valid   <= 1'b1;
            data_send_payload <= b;
            @(posedge clock);
            data_send_valid   <= 1'b0;
        end
    endtask

    //
    // Watchdog: never let the simulation hang forever.
    //

    initial begin
        #TIMEOUT_NS;
        $fatal(1, "FAIL: Timed out after %0d ns without finishing the test sequence", TIMEOUT_NS);
    end

    //
    // Main sequence
    //

    integer   test_i;
    reg [7:0] rx_byte;
    reg       stop_ok;

    // Alternating patterns plus edge cases (all-zero, all-ones).
    reg [7:0] test_bytes [0:4];
    reg [7:0] expected;

    initial begin
        $dumpfile("build/uart_sender_tb.vcd");
        $dumpvars(0, uart_sender_tb);

        data_send_valid   = 1'b0;
        data_send_payload = 8'h0;

        test_bytes[0] = 8'h55;  // 0b01010101
        test_bytes[1] = 8'hA3;  // 0b10100011
        test_bytes[2] = 8'h00;
        test_bytes[3] = 8'hFF;
        test_bytes[4] = 8'hC0;

        // Let the sender come out of reset / reach idle.
        repeat (5) @(posedge clock);

        for (test_i = 0; test_i < NUM_TEST_BYTES; test_i = test_i + 1) begin
            expected = test_bytes[test_i];
            $display("[%0t] Sending byte %0d/%0d: 0x%02h", $time, test_i + 1, NUM_TEST_BYTES, expected);

            fork
                send_byte(expected);
                uart_rx_byte(rx_byte, stop_ok);
            join

            if (^rx_byte === 1'bx) begin
                $fatal(1, "FAIL: Received undefined (X) bits, expected 0x%02h", expected);
            end
            if (rx_byte !== expected) begin
                $fatal(1, "FAIL: Expected 0x%02h, received 0x%02h", expected, rx_byte);
            end
            if (!stop_ok) begin
                $fatal(1, "FAIL: Stop bit was not high for byte 0x%02h", expected);
            end
            $display("[%0t] Byte 0x%02h received correctly (stop bit ok)", $time, rx_byte);

            // Idle a bit between frames.
            repeat (2 * BIT_CYCLES) @(posedge clock);
        end

        $display("PASS: All %0d bytes transmitted and received correctly", test_i);
        $finish;
    end

endmodule
